sys_atf_step.inputs:
(function(outputs, steps, stepResult) {
  var gate = new x_ssa_day2_ops.EntraHelpdeskGate();
  var same = 'day2-requester-sysid';
  var verdict = gate.preflight({ requester_id: same, approver_id: same, privileged: false });
  if (verdict.ok) { stepResult.setFailed('SoD violated: gate approved a self-approved request'); return; }
  if (String(verdict.reason || '').indexOf('CM-5') === -1) {
    stepResult.setFailed('refused, but not for the SoD/CM-5 reason: ' + verdict.reason); return;
  }
  stepResult.setSuccess();
})(outputs, steps, stepResult);
